import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    f = (x1**2 + x2**2 + x1 * x2) + 0.2*(x1**3 + x2**3) + 0.3*x1 + 0.1*x2
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x[0], x[1]
    return float(0.6* (x1**2 + x2**2) + 0.2 * x1 * x2 + 0.1 * np.exp(-0.2*(x1+x2)**2) + 0.1*(x1 - 0.5*x2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    f = (x1**2 + x2**2) + 0.1*(x1**3 + x2**3) + 0.3*x1
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (
        0.02 * (x1**2 + x2**2)
        + 0.08 * np.sin(4 * x1)
        + 0.04 * (x1 + x2 + x1 * x2)
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    f = (x1**4 + x2**4 + 0.5*x1**2*x2**2 + x1 * x2 + x1**3*x2 if -5 <= x1 <= 5 and -5 <= x2 <= 5 else (x1**2 + x2**2) * 10) + np.exp(0.1 * x1 * x2) + 0.5*x1 + 0.2*x2
    return float(f)

