import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    f = (x1**2 + x2**2) + 0.1*(x1**3 + x2**3) + 0.2*x1
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (
        0.1 * (x1**2 + x2**2)
        + 0.005 * (x1**3 + x2**3)
        + 0.1 * np.exp(-0.1 * (x1**2 + x2**2))
        + 0.05 * (x1 + x2)
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (
        0.1 * (x1**2 + x2**2)  # Quadratic bowl
        + 0.2 * x1 # Linear skew
        + 0.1*np.exp(-0.5*((x1-1)**2 + (x2-1)**2)) # Gaussian peak
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (
        0.1 * (x1**2 + x2**2)
        + 0.1 * np.exp(0.1 * x1 * x2)
        + 0.2 * np.exp(-0.2 * (x1**2 + x2**2))
        + 0.05 * (x1 + x2)
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (
        0.1 * (x1**2 + x2**2)
        + 0.2 * np.exp(-0.5 * (x1**2 + x2**2))
        + 0.05 * np.sin(3 * (x1 + x2))
        + 0.02 * (x1 + x2)
    )
